CREATE TABLE events(id TEXT PRIMARY KEY, revision INTEGER NOT NULL, schedule_revision INTEGER NOT NULL, spatial_revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','archived','cancelled')), event_json TEXT NOT NULL, public_revision INTEGER, last_op TEXT NOT NULL, last_digest TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX events_updated ON events(updated_at);
CREATE TABLE event_versions(event_id TEXT NOT NULL REFERENCES events(id), revision INTEGER NOT NULL, schedule_revision INTEGER NOT NULL, spatial_revision INTEGER NOT NULL, status TEXT NOT NULL, event_json TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(event_id,revision));
CREATE TABLE event_operations(scope TEXT NOT NULL, op TEXT NOT NULL, digest TEXT NOT NULL, result_json TEXT NOT NULL, event_id TEXT NOT NULL REFERENCES events(id), PRIMARY KEY(scope,op));
CREATE TABLE personal_plans(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), token_hash TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL DEFAULT 0, schedule_revision INTEGER NOT NULL, spatial_revision INTEGER NOT NULL, plan_json TEXT NOT NULL, availability_json TEXT NOT NULL, create_op TEXT NOT NULL, create_digest TEXT NOT NULL, last_op TEXT, last_digest TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX personal_event ON personal_plans(event_id);
CREATE TABLE personal_operations(scope TEXT NOT NULL, op TEXT NOT NULL, digest TEXT NOT NULL, result_json TEXT NOT NULL, personal_id TEXT NOT NULL REFERENCES personal_plans(id) ON DELETE CASCADE, PRIMARY KEY(scope,op));
CREATE TABLE personal_tombstones(id TEXT PRIMARY KEY, event_id TEXT NOT NULL, token_hash TEXT NOT NULL, op TEXT NOT NULL, digest TEXT NOT NULL, deleted_at TEXT NOT NULL);
CREATE TABLE personal_member_links(personal_id TEXT NOT NULL REFERENCES personal_plans(id) ON DELETE CASCADE, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(personal_id,member_id));
ALTER TABLE groups ADD COLUMN source_event_id TEXT REFERENCES events(id);
ALTER TABLE groups ADD COLUMN source_event_revision INTEGER;
ALTER TABLE groups ADD COLUMN source_schedule_revision INTEGER;
ALTER TABLE groups ADD COLUMN source_spatial_revision INTEGER;
CREATE INDEX groups_source_event ON groups(source_event_id);
CREATE TABLE media_assets(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), asset_key TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processing','ready','failed','revoked')), mime_type TEXT, width INTEGER, height INTEGER, size_bytes INTEGER, sha256 TEXT, display_size_bytes INTEGER, revision INTEGER NOT NULL DEFAULT 1, expected_event_revision INTEGER NOT NULL, ticket_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, operation_id TEXT NOT NULL, operation_digest TEXT NOT NULL, blob_path TEXT, declared_size_bytes INTEGER, declared_mime_type TEXT, source_path TEXT, display_path TEXT, display_mime_type TEXT, display_width INTEGER, display_height INTEGER, source_size_bytes INTEGER, source_sha256 TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX media_assets_event ON media_assets(event_id,asset_key,revision);
INSERT INTO events(id,revision,schedule_revision,spatial_revision,status,event_json,public_revision,last_op,last_digest,created_at,updated_at) SELECT t.id,t.revision,0,0,CASE WHEN t.published=1 THEN 'published' ELSE 'draft' END,t.event_json,CASE WHEN t.published=1 THEN t.revision ELSE NULL END,'legacy-template-migration','legacy-template-migration',t.updated_at,t.updated_at FROM templates t WHERE NOT EXISTS(SELECT 1 FROM templates newer WHERE newer.id=t.id AND newer.revision>t.revision);
INSERT INTO event_versions(event_id,revision,schedule_revision,spatial_revision,status,event_json,updated_at) SELECT id,revision,0,0,CASE WHEN published=1 THEN 'published' ELSE 'draft' END,event_json,updated_at FROM templates;
CREATE TRIGGER audit_event_insert AFTER INSERT ON events BEGIN INSERT INTO audit(action,group_id,resource_id,created_at) VALUES('event.created',NULL,NEW.id,NEW.updated_at); END;
CREATE TRIGGER audit_event_update AFTER UPDATE ON events BEGIN INSERT INTO audit(action,group_id,resource_id,created_at) VALUES('event.updated',NULL,NEW.id,NEW.updated_at); END;
